UPDATE public.site_images SET image_metadata = '{"text":"Organizujemy wieczory i imprezy tematyczne dla firm: integracje zespołów, jubileusze, gale oraz spotkania po konferencjach. Motyw wydarzenia łączymy z muzyką, oprawą sali i programem dla gości.","text2":"Dobieramy scenariusz, prowadzenie, dekoracje, nagłośnienie, oświetlenie i multimedia do obiektu oraz uczestników. Atrakcje i występy potwierdzamy w indywidualnej ofercie. Catering, salę i noclegi uzgadniamy osobno z organizatorem i obiektem."}'::jsonb, updated_at = now() WHERE id = '9553b033-4f6d-467a-8296-2f1e8cde26f6' AND image_metadata IS NOT DISTINCT FROM '{"text":"Organizujemy profesjonalne wieczory tematyczne, bale kostiumowe, imprezy z motywem przewodnim i eventy scenograficzne dla firm i klientów indywidualnych w całej Polsce. Tworzymy immersyjne doświadczenia, które przenoszą gości w inny świat. sss","text2":"Zapewniamy kompletną produkcję wieczoru tematycznego: scenografię, dekoracje, oświetlenie, nagłośnienie, catering tematyczny, animacje, pokazy artystyczne i profesjonalnego konferansjera."}'::jsonb;

UPDATE public.site_images SET image_metadata = '{"items":[{"image":"https://fuuljhhuhfojtmmfmskq.supabase.co/storage/v1/object/public/site-images/themed-party/1783085155276-k68hm.jpg","title":"Wieczór w stylu Las Vegas","keywords":"impreza Las Vegas, wieczór kasynowy, event kasyno, impreza glamour","description":"Kasyno rozrywkowe z ruletką, blackjackiem lub pokerem jako przestrzeń do rozmów i wspólnej zabawy. Goście poznają zasady przy stołach, a program można połączyć z DJ-em i oprawą glamour. Dobór stołów, dekoracji i godzin gry ustalamy w ofercie; zabawa odbywa się bez zakładów pieniężnych."},{"image":"https://fuuljhhuhfojtmmfmskq.supabase.co/storage/v1/object/public/site-images/themed-party/1783085396952-8u8olr.jpg","title":"Wieczór w klimacie PRL","keywords":"impreza PRL, wieczór retro, event lata 80, zabawa w stylu PRL","description":"Wieczór retro dla firm: muzyka znana z dawnych dekad, stylizowana oprawa i wspólny quiz. Pytania oraz zabawy mogą nawiązywać do historii firmy i wspomnień uczestników. Charakter dekoracji, prowadzenie i program dobieramy do grupy."},{"image":"https://fuuljhhuhfojtmmfmskq.supabase.co/storage/v1/object/public/site-images/themed-party/1783085741224-317f1r.jpg","title":"Wieczór James Bond","keywords":"impreza James Bond, wieczór Casino Royale, event szpiegowski","description":"Elegancki motyw szpiegowski na bankiet lub integrację. Kasyno rozrywkowe, muzyka filmowa i quiz mogą tworzyć kolejne części wieczoru. Scenariusz, dekoracje i ewentualne występy artystyczne wymagają osobnego ustalenia w ofercie."},{"image":"https://fuuljhhuhfojtmmfmskq.supabase.co/storage/v1/object/public/site-images/themed-party/1783086186282-y197ir.jpg","title":"Wieczór Gatsby / Lata 20.","keywords":"impreza Gatsby, wieczór lat 20, event art deco, charleston party","description":"Motyw lat 20. na galę, jubileusz firmy lub taneczny wieczór. Łączymy oprawę inspirowaną art déco z muzyką i prowadzeniem; program można rozszerzyć o kasyno rozrywkowe oraz występ artystyczny. Wybrane elementy i ich zakres potwierdzamy przed realizacją."},{"image":"https://fuuljhhuhfojtmmfmskq.supabase.co/storage/v1/object/public/site-images/themed-party/1783084794669-c69xof.jpg","title":"Wieczór disco / lata 80.","keywords":"impreza disco, wieczór lat 80, event retro disco","description":"Taneczna integracja z DJ-em, przebojami dawnych dekad i światłem dopasowanym do parkietu. Muzyczny quiz lub teleturniej może otworzyć wieczór i pomóc zespołom się poznać. Repertuar i poziom aktywności uczestników ustalamy wspólnie."},{"image":"https://fuuljhhuhfojtmmfmskq.supabase.co/storage/v1/object/public/site-images/themed-party/1783084888692-45zq2w.jpg","title":"Wieczór w stylu Hollywood","keywords":"impreza Hollywood, wieczór filmowy, gala oscarowa","description":"Filmowa oprawa gali z podziękowaniami, prezentacją osiągnięć i wręczeniem firmowych wyróżnień. Scenariusz łączy wystąpienia, muzykę i materiały na ekranie z późniejszą zabawą. Dekoracje, multimedia i prowadzenie dobieramy do miejsca oraz programu."},{"image":"https://fuuljhhuhfojtmmfmskq.supabase.co/storage/v1/object/public/site-images/themed-party/1783084809399-v1awaj.jpg","title":"Wieczór w stylu włoskim - Dolce Vita","keywords":"impreza włoska, wieczór dolce vita, event italia","description":"Swobodny wieczór firmowy inspirowany włoską atmosferą: muzyka, rozmowy i taneczna część spotkania. Klimat budujemy wybraną oprawą oraz światłem. Menu uzgadniamy z organizatorem i obiektem; catering lub dodatkowe pokazy nie są domyślnym elementem realizacji."},{"image":"https://fuuljhhuhfojtmmfmskq.supabase.co/storage/v1/object/public/site-images/themed-party/1783084359164-c1wv2.jpg","title":"Wieczór maskaradowy - Wenecja","keywords":"bal maskowy, wieczór wenecki, maskarada firmowa","description":"Motyw weneckiego balu na elegancką imprezę firmową. Maski, zaproszenie do wspólnego dress code’u i muzyka mogą połączyć gości wokół jednego tematu. Dobieramy prowadzenie, oprawę świetlną i zakres dekoracji do wybranego scenariusza."},{"image":"https://fuuljhhuhfojtmmfmskq.supabase.co/storage/v1/object/public/site-images/themed-party/1783083904539-3xm6q.jpg","title":"Wieczór hawajski - Aloha Party","keywords":"","description":"Tropikalny motyw na mniej formalną integrację: rytmy latino, taniec i wspólna zabawa. Wieczór można rozpocząć quizem lub teleturniejem zespołowym. Dekoracje, muzykę oraz aktywności dopasowujemy do sali i uczestników; realizacja plenerowa wymaga planu na pogodę."},{"image":"https://fuuljhhuhfojtmmfmskq.supabase.co/storage/v1/object/public/site-images/themed-party/1783085834769-shlyn9.jpg","title":"Wieczór Mafijny - Ojciec Chrzestny","keywords":"","description":"Filmowy motyw na stylizowany bankiet: elegancki dress code, odpowiednio dobrana muzyka i światło. Program można uzupełnić o kasyno rozrywkowe lub quiz filmowy. Zakres scenografii i atrakcji potwierdzamy w indywidualnej ofercie."}]}'::jsonb, updated_at = now() WHERE id = '4f4faf1e-b723-4438-8b57-fb441077c34e' AND image_metadata IS NOT DISTINCT FROM '{"items":[{"image":"https://fuuljhhuhfojtmmfmskq.supabase.co/storage/v1/object/public/site-images/themed-party/1783085155276-k68hm.jpg","title":"Wieczór w stylu Las Vegas","keywords":"impreza Las Vegas, wieczór kasynowy, event kasyno, impreza glamour","description":"Kasyno rozrywkowe, neonowe dekoracje, hostessy, dress code glamour. Stoły do ruletki, blackjacka i pokera. Muzyka lounge i koktajle."},{"image":"https://fuuljhhuhfojtmmfmskq.supabase.co/storage/v1/object/public/site-images/themed-party/1783085396952-8u8olr.jpg","title":"Wieczór w klimacie PRL","keywords":"impreza PRL, wieczór retro, event lata 80, zabawa w stylu PRL","description":"Dekoracje z epoki, plakaty propagandowe, bar mleczny, muzyka lat 60-80. Zabawy i konkursy w stylu retro. Dress code robotniczy lub dyskotekowy."},{"image":"https://fuuljhhuhfojtmmfmskq.supabase.co/storage/v1/object/public/site-images/themed-party/1783085741224-317f1r.jpg","title":"Wieczór James Bond","keywords":"impreza James Bond, wieczór Casino Royale, event szpiegowski","description":"Elegancki wieczór agentów. Stroje wieczorowe, koktajle, kasyno, pokazy kaskaderskie. Muzyka filmowa na żywo."},{"image":"https://fuuljhhuhfojtmmfmskq.supabase.co/storage/v1/object/public/site-images/themed-party/1783086186282-y197ir.jpg","title":"Wieczór Gatsby / Lata 20.","keywords":"impreza Gatsby, wieczór lat 20, event art deco, charleston party","description":"Szalone lata dwudzieste: art deco, frędzelki, charleston, jazz na żywo, bąbelki szampana. Prohibicja bar z koktajlami epoki."},{"image":"https://fuuljhhuhfojtmmfmskq.supabase.co/storage/v1/object/public/site-images/themed-party/1783084794669-c69xof.jpg","title":"Wieczór disco / lata 80.","keywords":"impreza disco, wieczór lat 80, event retro disco","description":"Kula dyskotekowa, neony, retro muzyka, karaoke. Dress code fluorescencyjny, konkursy taneczne. DJ z hitami lat 70-80."},{"image":"https://fuuljhhuhfojtmmfmskq.supabase.co/storage/v1/object/public/site-images/themed-party/1783084888692-45zq2w.jpg","title":"Wieczór w stylu Hollywood","keywords":"impreza Hollywood, wieczór filmowy, gala oscarowa","description":"Czerwony dywan, Oscary firmowe, paparazzi, fotobudka filmowa. Gala z wręczeniem nagród, oprawa jak na wielkim festiwalu."},{"image":"https://fuuljhhuhfojtmmfmskq.supabase.co/storage/v1/object/public/site-images/themed-party/1783084809399-v1awaj.jpg","title":"Wieczór w stylu włoskim - Dolce Vita","keywords":"impreza włoska, wieczór dolce vita, event italia","description":"Romantyczna atmosfera Włoch: wino, ser, oliwa. Muzyka italiana na żywo, dekoracje toskańskie, pokaz gotowania pasta."},{"image":"https://fuuljhhuhfojtmmfmskq.supabase.co/storage/v1/object/public/site-images/themed-party/1783084359164-c1wv2.jpg","title":"Wieczór maskaradowy - Wenecja","keywords":"bal maskowy, wieczór wenecki, maskarada firmowa","description":"Maski weneckie, kostiumy karnawałowe, złoto i purpura. Muzyka barokowa, pokazy cyrkowe, tajemnicza atmosfera balu."},{"image":"https://fuuljhhuhfojtmmfmskq.supabase.co/storage/v1/object/public/site-images/themed-party/1783083904539-3xm6q.jpg","title":"Wieczór hawajski - Aloha Party","keywords":"","description":"Opis tematyki...ropikalne dekoracje, leje z kwiatów, tiki bar, koktajle egzotyczne. Taniec hula, konkurs limbo, muzyka reggae."},{"image":"https://fuuljhhuhfojtmmfmskq.supabase.co/storage/v1/object/public/site-images/themed-party/1783085834769-shlyn9.jpg","title":"Wieczór Mafijny - Ojciec Chrzestny","keywords":"","description":"Opis tematyki...Klimat sycylijskiej mafii. Eleganckie garnitury, cygara, włoskie przysmaki, muzyka na żywo i niezapomniana atmosfera „Ojca Chrzestnego”."}]}'::jsonb;

INSERT INTO public.seo_city_content (id, page_slug, city, region, custom_title, custom_description, custom_h1, local_features, is_active) SELECT '23e79c0b-e314-4699-99ec-c3ec14f047b8', 'wieczory-tematyczne', 'olsztyn', 'warmińsko-mazurskie', 'Imprezy tematyczne dla firm Olsztyn | Wieczory MAVINCI', 'Imprezy i wieczory tematyczne dla firm w Olsztynie: Gatsby, Las Vegas, PRL, Hollywood. Scenariusz, DJ, dekoracje i własna technika MAVINCI. Zobacz realizacje.', 'Imprezy i wieczory tematyczne dla firm w Olsztynie', '{"intro_heading":"Impreza tematyczna, która łączy zespół","intro_text":"Temat wieczoru nadaje wspólny kierunek muzyce, oprawie sali i aktywnościom uczestników. Dla firmy oznacza to spójny program zamiast przypadkowego zestawu atrakcji. W MAVINCI dopasowujemy scenariusz do celu spotkania: rozmów po konferencji, integracji zespołów, podziękowania pracownikom albo wspólnego świętowania. Możemy połączyć DJ-a i prowadzenie z quizem, teleturniejem, kasynem rozrywkowym lub ustalonym programem artystycznym.","planning_heading":"Wieczór firmowy w Olsztynie — organizacja i logistyka","planning_text":"Nasze biuro i magazyn przy ul. Towarowej 20B w Olsztynie są bazą przygotowania sprzętu i transportu. Przy wydarzeniu w hotelu lub sali bankietowej ustalamy z obiektem godziny dostępu, rozładunek, zasilanie i miejsce na technikę. Jeżeli wieczór odbywa się po konferencji w tej samej sali, planujemy zmianę ustawienia oraz próby przed wejściem gości. Obsługujemy też wydarzenia w okolicach Olsztyna, m.in. w kierunku Dywit, Stawigudy, Gietrzwałdu i Barczewa; dojazd i harmonogram uwzględniamy w indywidualnej ofercie.","planning_checks":["Adres obiektu i dostęp do sali przed rozpoczęciem wieczoru.","Liczba gości, układ stołów, parkiet i przestrzeń na atrakcje.","Przerwa między konferencją, kolacją a częścią rozrywkową.","Zasady obiektu dotyczące głośności, efektów i zakończenia imprezy."]}'::jsonb, true WHERE NOT EXISTS (SELECT 1 FROM public.seo_city_content WHERE page_slug = 'wieczory-tematyczne' AND city = 'olsztyn');

COMMIT;
